  rMe = `%1$s %`,
  iMe = `Toiminnon aktivoimiseksi painiketta on painettava ainakin %1$s.`,
  aMe = `%1$s aktivoituu painikkeen painalluksella. Komento ohitetaan, koska se on määritetty keskeytettäväksi.`,
  oMe = `Toiminto saa aikaan vain yhden komennon, joten määritettävien komentojen välillä ei ole ajoitusta. Viive luetellaan yhä alla.`,
  sMe = `Järjestä syötteet uudelleen aloitusajankohdan perusteella`,
