  SMe = `Asetukset`,
  CMe = `Valitse määritys komennolle %1$s`,
  wMe = `Valitse tila painikkeelle %1$s`,
  TMe = `Tekee pyyhkäisyn virtuaalisella ohjainsauvalla ja hyödyntää käyttäjän kosketuslevyn sijaintia määrittämään, kuinka pitkälle pyyhkäisy ulottuu.`,
  EMe = `Tekee pyyhkäisyn virtuaalisella ohjainsauvalla ja hyödyntää käyttäjän gyron sijaintia määrittämään, kuinka pitkälle pyyhkäisy ulottuu.`,
  DMe = `Siirtää hiiren osoitinta tasaisella nopeudella niin kauan, kun ohjaimella pyyhkäistään. Mitä pitemmälle työntö ulottuu, sitä nopeampi se on.`,
  OMe = `Siirtää hiiren osoitinta levyn liikuttamisen mukaan tavalla, joka muistuttaa kannettavan tietokoneen kosketuslevyä.`,
  kMe = `Ohjainsauvan vanhempi hiiritila, jota säilytetään sitä jo ennestään käyttäville määrityksille.`,
  AMe = `Muuntaa ohjaimen liikkeen hiiren liikkeeksi, jolloin tähtäys tapahtuu kallistamalla.`,
  jMe = `Lähettää kameran sauvan syötteen. Mitä pitemmälle ohjainta työnnetään, sitä nopeammin kamera kääntyy.`,
  MMe = `Muuntaa ohjaimen liikkeen kameran sauvasyötteeksi peleissä, joissa käytetään sauvaa hiiren sijasta.`,
  NMe = ` Muuntaa ohjaimen liikkeen sauvan pyyhkäisyksi, aivan kuin työntäisit sauvaa niin pitkälle.`,
  PMe = `Määrittää kosketuslevyn tiettyyn osaan näytöstä, jotta levyn kohta linkittyy aina samaan paikkaan.`,
  FMe = `Lähettää kamerakulman pelille suoraan, jos peli tukee toimintoa. Tällöin ei tarvita hiiren tai sauvan kaltaista muiden tilojen aikaansaamaa liikettä.`,
  IMe = `Kun tämä vaihtoehto on valittu, ohjain ei tee mitään.`,
  LMe = `Lähettää ohjainsauvasyötteen peliin, mutta lukee kosketuslevyn liikkeet kuin se olisi hiiri. Peleille, joissa oletetaan tähtäämisen tai kursorin liikuttamisen tapahtuvan sauvalla.`,
  RMe = `Lähettää ohjainsauvasyötteen peliin, mutta lukee gyron liikkeet kuin se olisi hiiri. Peleille, joissa oletetaan tähtäämisen tai kursorin liikuttamisen tapahtuvan sauvalla.`,
  zMe = `Pyyhkäisee sauvaa haluttuun suuntaan, jolloin myös kamera kohdistuu kyseiseen suuntaan. Tämän jälkeen sauvan kääntäminen kääntää myös kameraa yhtä paljon.`,
  BMe = `Tämän ohjaimen määrityksiä ei voi käyttää kyseisen toiminnon suorittamiseen tässä toimintosarjassa. Aseta ensin haluamasi määrityksen tila sen omalla sivulla.`,
