  T0e = `Gyro-syöte on päällä vain, kun oikeaa sauvaa tai kosketuslevyä kosketaan.`,
  E0e = `Käännä vaaka-akseli`,
  D0e = `Jos päällä, vasemmalle liikkuminen siirtää ohjainsauvaa oikealle, ja päinvastoin. Peleissä on usein tämä sama asetus, joten varmista, etteivät nämä kaksi asetusta kumoa toisiaan.`,
  O0e = `Käännä vaaka-akseli – Päällä`,
  k0e = `Jos päällä, vasemmalle liikkuminen siirtää ohjainsauvaa oikealle, ja päinvastoin. Peleissä on usein tämä sama asetus, joten varmista, etteivät nämä kaksi asetusta kumoa toisiaan.`,
  A0e = `Käännä vaaka-akseli – Pois`,
  j0e = `Ohjainsauvan vaaka-akseli toimii normaalisti, levyllä vasemmalle siirtyminen liikuttaa ohjainsauvaa vasemmalle.`,
  M0e = `Käännä pystyakseli`,
  N0e = `Jos päällä, levyllä ylöspäin liikkuminen siirtää ohjainsauvaa alaspäin, ja päinvastoin. Peleissä on usein tämä sama asetus, joten varmista, etteivät nämä kaksi asetusta kumoa toisiaan.`,
  P0e = `Käännä pystyakseli – Päällä`,
  F0e = `Jos päällä, levyllä ylöspäin liikkuminen siirtää ohjainsauvaa alaspäin, ja päinvastoin. Peleissä on usein tämä sama asetus, joten varmista, etteivät nämä kaksi asetusta kumoa toisiaan.`,
  I0e = `Käännä pystyakseli – Pois`,
  L0e = `Ohjainsauvan pysty-akseli toimii normaalisti, levyllä ylös siirtyminen liikuttaa ohjainsauvaa ylöspäin.`,
  R0e = `Herkkyys pystysuunnassa`,
  z0e = `Pystysuunnan herkkyys määräytyy sen mukaan, kuinka paljon pystysuuntaista liikettä esiintyy suhteessa vaakasuoraan liikkeeseen. Jos suhde on 50 %, liike on molempiin suuntiin yhtä voimakasta; jos alle 50 %, vaakasuora liike on voimakkaampaa; ja jos yli 50 %, pystysuuntainen liike on voimakkaampaa.`,
  B0e = `Ohjainsauvan tasoitus`,
  V0e = `Palauttaa sauvan lepoasentoonsa kuin sitä liikuttaisi fyysinen jousi, eikä välittömästi kosketuksen loputtua.`,
  H0e = `Ohjainsauvan tasoitus – Päällä`,
  U0e = `Palauttaa sauvan lepoasentoonsa kuin sitä liikuttaisi fyysinen jousi, eikä välittömästi kosketuksen loputtua.`,
  W0e = `Ohjainsauvan tasoitus – Pois`,
  G0e = `Palaa välittömästi nollaan syötteen päättyessä.`,
  K0e = `Hiiren herkkyys`,
  q0e = `Osoittimen herkkyys, kun virtuaalisen ohjainsauvan asetuksena on hiiri.`,
  J0e = `Kuolleen alueen esto`,
  Y0e = `Useimmat pelit määrittävät omat kuolleet alueensa ohjaimille. Jos ohjaus tuntuu tökkivän fyysisellä liikealueella, missä ei näy liikettä, se voi johtua pelin omasta kuolleesta alueesta. Voit poistaa sen kuolleen alueen estolla. Se poistaa kuolleen alueen ja antaa jäljelle jäävän tilalle paremman hallinnan. Mitä korkeammalla liukusäädin on, sitä enemmän lisätään pienimpään tiedon lähetysarvoon. Huomaa, että jos kaikki kuollut alue poistetaan, kaikki alueet lähettävät syötettä. Voit poistaa kuolleen alueen estolla myös vain osan kuolleesta alueesta, jopa silloinkin kun kuolleen alueen estoalue on suurempi kuin pelissä oleva itse kuollut alue.`,
  X0e = `Kuolleen alueen eston puskuri`,
  Z0e = `Jos kuolleen alueen esto on päällä, peliin ei välttämättä jää yhtään kuollutta aluetta, joten jokainen kohta lähettää liikekomentoja. Kuolleen alueen eston puskurilla voit jättää alueen, josta komentoja ei lähetetä. Sen voi visualisoida levyn keskeltä kulkevana säteenä, josta komentoja ei lähetetä.`,
  Q0e = `Näytä kuolleen alueen lisäasetukset`,
  $0e = `Hiiren herkkyys`,
  e2e = `Kuolleen alueen esto`,
  t2e = `Useimmat pelit määrittävät omat kuolleet alueensa ohjaimille. Jos ohjaus tuntuu tökkivän fyysisellä liikealueella, missä ei näy liikettä, se voi johtua pelin omasta kuolleesta alueesta. Voit poistaa sen kuolleen alueen estolla. Se poistaa kuolleen alueen ja antaa jäljelle jäävän tilalle paremman hallinnan. Mitä korkeammalla liukusäädin on, sitä enemmän lisätään pienimpään tiedon lähetysarvoon. Huomaa, että jos kaikki kuollut alue poistetaan, kaikki alueet lähettävät syötettä. Voit poistaa kuolleen alueen estolla myös vain osan kuolleesta alueesta, jopa silloinkin kun kuolleen alueen estoalue on suurempi kuin pelissä oleva itse kuollut alue.`,
