  Vat = `Liipaisinvaimennus aktivoitu vasemman liipaisimen kevyelle/vahvalle painallukselle. Liipaisimesta vetäminen hidastaa hiiren liikkeitä, kunnes liipaisin on pohjassa.`,
  Hat = `Vaimennus – Molempien liipaisimien kevyt/vahva painallus`,
  Uat = `Liipaisinvaimennus aktivoitu molempien liipaisimien kevyelle/vahvalla painallukselle. Kumman tahansa liipaisimen vetäminen hidastaa hiiren liikkeitä, kunnes liipaisin on pohjassa.`,
  Wat = `Liipaisinvaimennuksen vahvuus`,
  Gat = `Tämä säätää, miten paljon hiiren liikkuminen hidastuu. Liu'uta oikealle hidastaaksesi hiirtä enemmän.`,
  Kat = `Gyron käyttöönottopainike`,
  qat = `Gyro-syöte voidaan ottaa käyttöön vain painiketta painamalla.`,
