  Jot = `Vahva painallus`,
  Yot = `Tämä komento suoritetaan, kun painat liipaisimen täysin pohjaan niin, että siitä kuuluu vaimea naksahdus.`,
  Xot = `Toista pitämällä pohjassa (Turbo)`,
  Zot = `Toista pitämällä pohjassa (Turbo)`,
  Qot = `Toista pitämällä pohjassa (Turbo) – Päällä`,
  $ot = `Jos Turbo-tila on käytössä, minkä tahansa painikkeen pohjassa pitäminen toistaa painallusta.`,
  est = `Toista pitämällä pohjassa (Turbo) – Pois`,
  tst = `Jos Turbo-tila on käytössä, minkä tahansa painikkeen pohjassa pitäminen toistaa painallusta.`,
  nst = `Toistoväli`,
  rst = `Kun Turbo-tila on käytössä, tämä määrää toistonopeuden. Korkeamman toistonopeuden saat siirtämällä säädintä oikealle.`,
  ist = `Analogiliipaisin`,
  ast = `Kun päällä, valitun liipaisimen analogiarvo lähetetään pelille. Tämä on mahdollista vain, jos peli tunnistaa XInputia tukevat ohjainarvot.`,
  ost = `Analogiliipaisin – Pois`,
  sst = `Analogiarvoja ei lähetetä.`,
  cst = `Vasen liipaisin`,
  lst = `Analogiarvot lähetetään vasemmasta liipaisimesta. Tämä on mahdollista vain, jos peli tunnistaa XInputia tukevat ohjainarvot.`,
  ust = `Oikea liipaisin`,
  dst = `Analogiarvot lähetetään oikeasta liipaisimesta. Tämä on mahdollista vain, jos peli tunnistaa XInputia tukevat ohjainarvot.`,
  fst = `Liipaisinkantaman alku`,
  pst = `Tämä säätää analogiliipaisimen kuolleen alueen. Suurempi arvo määrittää suuremman kuolleen alueen, missä analogiarvoja ei lähetetä liipaisimen hipaisusta.`,
  mst = `Liipaisinkantaman loppu`,
  hst = `Tämä säätää analogiliipaisimen kuolleen alueen. Pienempi arvo määrittää pienemmän kuolleen alueen, missä enimmäisanalogiarvot lähetetään, kun liipaisimen katsotaan olevan pohjassa.`,
  gst = `Liipaisimen vastekäyrä`,
  _st = `Tämä määrää analogisen syötteen ja vasteen suhteen. Oletuksena käytetään lineaarista 1:1-suhdetta. Käyrää säätämällä voi korostaa tai vähentää hienosäätöä.`,
  vst = `Vastekäyrä – Lineaarinen`,
  yst = `Lineaarisessa vastekäyrässä syöte ja sen vaste ovat yhtä suuret. 50 %:n poikkeama syötteessä vastaa 50 %:n siirtymää.`,
  bst = `Vastekäyrä – Aggressiivinen`,
  xst = `Aggressiivinen vastekäyrä nousee 100 %:iin nopeammin. Tällöin hitaan liikkeen alue on pieni ja korkeiden arvojen alue saavutetaan nopeasti.`,
  Sst = `Vastekäyrä – Rento`,
  Cst = `Rento vastekäyrä nousee 100 %:iin hitaammin. Hitaan liikkeen alue on suurempi, mikä mahdollistaa tarkemman ohjaamisen. Suurien arvojen alue on lähempänä loppua.`,
  wst = `Vastekäyrä – Leveä`,
  Tst = `Leveä vastekäyrä nousee 100 %:iin paljon hitaammin kuin oletus. Pienten arvojen alue on leveä, ja se nousee jyrkästi lähellä loppua. Tämä mahdollistaa tarkan ohjaamisen sisäreunalla ja antaa silti täyden vasteen pohjassa.`,
  Est = `Vastekäyrä – Erittäin leveä`,
  Dst = `Erittäin leveä vastekäyrä antaa pieniä arvoja suurella alueella ja saavuttaa 100 % vasta aivan reunalla.`,
  Ost = `Vastekäyrä – Mukautettu käyrä`,
  kst = `Mukautettu käyrä voidaan määrittää vastekäyräliukusäätimellä.`,
  Ast = `Mukautettu vastekäyrä`,
  jst = `Muuta tällä liukusäätimellä liipaisimen vastekäyrää.`,
  Mst = `Kevyt painallus`,
  Nst = `Tämä komento suoritetaan, kun painat liipaisinta kevyesti, mutta ei pohjaan saakka (et kuule naksahdusta).`,
  Pst = `Liipaisinkynnys`,
  Fst = `Kevyt painallus -komento lähetetään, kun liipasinta painetaan tähän kynnykseen saakka.  Kevyt painallus riittää, kun liukusäädin on vasemmassa päässä, ja oikeassa päässä vaaditaan vahva painallus.`,
  Ist = `Liipaisinkynnyksen tyyli`,
  Lst = `Peleissä, joissa on käytössä sekä kaksivaiheinen liipaisin että klikkaus, lonkkalaukauksessa nopea painallus siirtyy suoraan klikkaukseen ilman kaksivaiheista komentoa, kun hitaampi painallus aktivoi kaksivaiheisen komennon ensin. Aggressiivinen lonkkalaukaus ottaa kevyen painalluksen komennon paljon nopeammin kuin rauhallinen lonkkalaukaus.`,
  Rst = `Hyvä vaihtoehto hiiren klikkauksille ja vedoille. Liipaisimen painallus lähettää ensin kevyen painalluksen ja sitten vahvan painalluksen.`,
  zst = `Sopii toimintapeleille, joissa lähetetään kevyt painallus -komentoja nopeilla painalluksilla ja vapautuksilla.`,
  Bst = `Sopii toimintapeleille, joissa on määritys sekä vahvalle että kevyelle painallukselle. Nopea painallus lähettää vain vahvan painalluksen. Hitaampi painallus lähettää ensin kevyen ja sitten vahvan painalluksen.`,
  Vst = `Sama kuin yllä, mutta kevyt painallus voidaan ohittaa kauemmin.`,
  Hst = `Kevyt painallus voidaan ohittaa vieläkin kauemmin.`,
  Ust = `Kuten yllä, mutta kun joko vahva tai kevyt painallus on lähetetty, toista ei voida lähettää, ennen kuin liipaisin on kokonaan vapautettu.`,
  Wst = `Herkän liipaisimen kynnys`,
  Gst = `Herkän liipaisimen kynnys voi tarvittaessa mukautua käyttäjänsä mukaan. Kun kynnys on ylitetty, pieninkin liipaisimesta hellittäminen nollaa liipaisimen ja aktivoi painallustoiminnon, vaikka liipaisin ei olisikaan palautunut alkuasemaansa. Tämä sopii hyvin esimerkiksi räiskintäpeleissä oleviin tilanteisiin, joissa ensimmäisen laukauksen ei kuulu olla äärimmäisen herkkä, mutta jatkolaukausten tulee tulla luonnostaan. Jos komento vaatii liipaisimen pitämistä jatkuvasti pohjassa, ominaisuus ei välttämättä ole eduksi, sillä pieninkin hellittäminen johtaa valitun komennon laukaisemiseen.`,
  Kst = `Yksinkertainen kynnys`,
  qst = `Peruskynnys, jossa kynnys pysyy samana valitussa arvossaan. Kun kynnys ylitetään, liipaisimen vapautus ei päästä irti painikkeesta, ennen kuin liipaisin alittaa jälleen kynnyksen. Jos komennot vaativat jatkuvaa liipaisimen pohjassa pitoa, tämä on suositeltu asetus.`,
  Jst = `Voimakas lonkkalaukaus`,
  Yst = `Kaksitoimisille liipaisimille luotu lonkkalaukausasetus sallii sen, että nopea liipaisimen veto aktivoi vahvan painalluksen kommennon ilman kevyttä painallusta. Hitaampi veto katsoo painalluksen kevyeksi. Tämän avulla esimerkiksi tähtäämisen voi asettaa kevyeen painallukseen ja ampumisen vahvaan painallukseen, jonka myötä voi myös ampua nopeasti ilman tähtäämistä, eikä kevyen painalluksen komennon aktivoidu, ellei liipaisin alita kynnystä. Aggressiivinen lonkkalaukaus reagoi kevyellä painalluksella hyvin nopeasti, jonka myötä yksinäinen vahva painallus vaatii myös nopean vedon.`,
  Xst = `Normaali lonkkalaukaus`,
  Zst = `Kaksitoimisille liipaisimille luotu lonkkalaukausasetus sallii sen, että nopea liipaisimen veto aktivoi vahvan painalluksen kommennon ilman kevyttä painallusta. Hitaampi veto katsoo painalluksen kevyeksi. Tämän avulla esimerkiksi tähtäämisen voi asettaa kevyeen painallukseen ja ampumisen vahvaan painallukseen, jonka myötä voi myös ampua nopeasti ilman tähtäämistä, eikä kevyen painalluksen komennon aktivoidu, ellei liipaisin alita kynnystä. Aggressiivinen lonkkalaukaus reagoi kevyellä painalluksella hyvin nopeasti, jonka myötä yksinäinen vahva painallus vaatii myös nopean vedon.`,
