  Qmt = `Aktivaattorin tyyppi`,
  $mt = `Aktivaattorit määrittävät, kuinka syöte vastaa. Onko se perus-, tupla- vai pitkä painallus? Valitse tai poista ne täältä.`,
  eht = `Ei käytössä – Poista aktivaattori`,
  tht = `Tämä valinta poistaa aktivaattorin ja kaikki sen komennot.`,
  nht = `Peruspainallus`,
  rht = `Peruspainalluksen aktivaattori on oletustyyppi. Kun painat painiketta, se käynnistyy ja pysyy käynnissä, kunnes painike vapautetaan.`,
  iht = `Tuplapainallus`,
  aht = `Tuplapainalluksen aktivaattorin käynnistys vaatii syötteen nopean tuplapainalluksen. Jos toinen painallus jätetään pohjaan, se pysyy pohjassa. Kun tuplapainallus käynnistetään, mikään keskeytettävä aktivaattori samassa painikkeessa ei käynnisty ja odottaa, kunnes tuplapainallus on ohi.`,
  oht = `Pitkä painallus`,
  sht = `Pitkän painalluksen aktivaattori käynnistyy pitämällä painiketta pohjassa tietyn ajan. Kun pitkän painalluksen vaatima aika on kulunut, se pysyy aktiivisena niin kauan kuin painiketta pidetään pohjassa. Kun pitkä painallus käynnistetään, mikään keskeytettävä aktivaattori samassa painikkeessa ei käynnisty ja odottaa, kunnes pitkä painallus on ohi.`,
  cht = `Aloituspainallus`,
  lht = `Aloituspainalluksen aktivaattori käynnistyy, kun painiketta painetaan. Se sammuu välittömästi, vaikka painike pidettäisiin pohjassa. Tämä on kätevä erityisesti yhdessä vapautuspainalluksen aktivaattorin kanssa, jos halutaan muuttaa vaihto pidoksi, kuten kyyristymistilan komennossa.`,
  uht = `Vapautuspainallus`,
  dht = `Vapautuspainalluksen aktivaattori käynnistyy ja sammuu, kun painike vapautetaan.`,
  fht = `Kevyt painallus`,
  pht = `Kevyen painalluksen aktivaattori aktivoituu, kun painiketta tai liipaisinta painetaan osittain.`,
  mht = `Analoginen`,
  hht = `Analoginen aktivaattori tuottaa analogisen ulostulon.`,
  ght = `Vaihtopainike`,
  _ht = `Näppäinyhdistelmät otetaan käyttöön painamalla samanaikaisesti aktivointi- ja vaihtonäppäintä.`,
  vht = `Komento`,
  yht = `Voit määrittää aktivaattoriin yhden tai useamman komennon.`,
  bht = `Aktivoi analoginen sauva / kosketuslevy`,
  xht = `Virtuaaliselle ohjaimelle voi luoda virtuaalisen ohjainsauvan tai kosketuslevyn, joka toimii, kun painiketta pidetään painettuna. Näin konekiväärillä voi tähdätä samalla sormella, jolla painetaan liipaisinta.`,
  Sht = `Ei analogista sauvaa / kosketuslevyä`,
  Cht = `Aktivaattori toimii normaalisti eikä aktivoi virtuaalista analogista sauvaa tai kosketuslevyä.`,
  wht = `Aktivoi vasen analoginen sauva`,
  Tht = `Painikkeita painettaessa samalla sormella kontrolloidaan vasenta virtuaalista analogista sauvaa.`,
